package io.github.diodeme.ji.cli;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import io.github.diodeme.ji.host.HostDeviceStore;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.nio.file.attribute.PosixFilePermission;
import java.security.GeneralSecurityException;
import java.security.KeyFactory;
import java.security.KeyPair;
import java.security.KeyPairGenerator;
import java.security.spec.PKCS8EncodedKeySpec;
import java.security.spec.X509EncodedKeySpec;
import java.util.Base64;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;

/** Atomic owner-only file store for Host identity and direct paired devices. */
final class FileHostDeviceStore implements HostDeviceStore {
    private static final ObjectMapper MAPPER = new ObjectMapper();
    private final Path file;
    private final KeyPair identity;
    private final Map<String, Device> devices = new LinkedHashMap<>();

    FileHostDeviceStore(Path file) {
        this.file = file.toAbsolutePath().normalize();
        if (Files.exists(this.file)) {
            identity = load();
        } else {
            identity = generate();
            persist();
        }
    }

    @Override public synchronized KeyPair identity() { return identity; }
    @Override public synchronized Optional<Device> device(String deviceId) {
        return Optional.ofNullable(devices.get(deviceId));
    }
    @Override public synchronized List<Device> devices() { return List.copyOf(devices.values()); }
    @Override public synchronized void save(Device device) {
        Device current = devices.get(device.deviceId());
        if (current != null && !java.security.MessageDigest.isEqual(current.publicKey(), device.publicKey())) {
            throw new IllegalArgumentException("device identity changed");
        }
        devices.put(device.deviceId(), device);
        persist();
    }
    @Override public synchronized void remove(String deviceId) {
        if (devices.remove(deviceId) != null) persist();
    }

    private KeyPair load() {
        try {
            rejectInsecureFile();
            Map<String, Object> value = MAPPER.readValue(file.toFile(), new TypeReference<>() {});
            if (!"ji-host-identity-v1".equals(value.get("format"))) throw new IOException("invalid format");
            var factory = KeyFactory.getInstance("Ed25519");
            var pair = new KeyPair(
                    factory.generatePublic(new X509EncodedKeySpec(decode(value.get("publicKey")))),
                    factory.generatePrivate(new PKCS8EncodedKeySpec(decode(value.get("privateKey")))));
            Object rawDevices = value.get("devices");
            if (!(rawDevices instanceof List<?> values)) throw new IOException("invalid devices");
            for (Object raw : values) {
                if (!(raw instanceof Map<?, ?> item)) throw new IOException("invalid device");
                Device device = new Device(String.valueOf(item.get("deviceId")),
                        Base64.getDecoder().decode(String.valueOf(item.get("publicKey"))),
                        String.valueOf(item.get("role")));
                if (devices.putIfAbsent(device.deviceId(), device) != null) throw new IOException("duplicate device");
            }
            return pair;
        } catch (IOException | GeneralSecurityException | IllegalArgumentException failure) {
            throw new IllegalStateException("Host identity store is unavailable", failure);
        }
    }

    private void persist() {
        try {
            Files.createDirectories(file.getParent());
            Path temporary = Files.createTempFile(file.getParent(), file.getFileName().toString(), ".tmp");
            try {
                setOwnerOnly(temporary);
                MAPPER.writeValue(temporary.toFile(), Map.of(
                        "format", "ji-host-identity-v1",
                        "privateKey", Base64.getEncoder().encodeToString(identity.getPrivate().getEncoded()),
                        "publicKey", Base64.getEncoder().encodeToString(identity.getPublic().getEncoded()),
                        "devices", devices.values().stream().map(device -> Map.of(
                                "deviceId", device.deviceId(),
                                "publicKey", Base64.getEncoder().encodeToString(device.publicKey()),
                                "role", device.role())).toList()));
                try {
                    Files.move(temporary, file, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
                } catch (java.nio.file.AtomicMoveNotSupportedException unsupported) {
                    Files.move(temporary, file, StandardCopyOption.REPLACE_EXISTING);
                }
                setOwnerOnly(file);
            } finally {
                Files.deleteIfExists(temporary);
            }
        } catch (IOException failure) {
            throw new IllegalStateException("Host identity store write failed", failure);
        }
    }

    private void rejectInsecureFile() throws IOException {
        if (Files.isSymbolicLink(file) || !Files.isRegularFile(file, java.nio.file.LinkOption.NOFOLLOW_LINKS)) {
            throw new SecurityException("Host identity must be a regular non-link file");
        }
        if (Files.getFileStore(file).supportsFileAttributeView("posix")) {
            Set<PosixFilePermission> permissions = Files.getPosixFilePermissions(file,
                    java.nio.file.LinkOption.NOFOLLOW_LINKS);
            if (!permissions.equals(Set.of(PosixFilePermission.OWNER_READ, PosixFilePermission.OWNER_WRITE))) {
                throw new SecurityException("Host identity permissions must be 0600");
            }
        }
    }

    private static void setOwnerOnly(Path path) throws IOException {
        if (Files.getFileStore(path).supportsFileAttributeView("posix")) {
            Files.setPosixFilePermissions(path, Set.of(
                    PosixFilePermission.OWNER_READ, PosixFilePermission.OWNER_WRITE));
        }
    }

    private static KeyPair generate() {
        try {
            return KeyPairGenerator.getInstance("Ed25519").generateKeyPair();
        } catch (GeneralSecurityException impossible) {
            throw new IllegalStateException(impossible);
        }
    }

    private static byte[] decode(Object value) {
        return Base64.getDecoder().decode(String.valueOf(value));
    }
}
